<?php
if(PHP_SAPI!=='cli'||basename(__DIR__)!=='nuers.net')exit(1);
umask(0077);require __DIR__.'/httpdocs/vendor/autoload.php';$app=require __DIR__.'/httpdocs/bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
$root=base_path();$dir=storage_path('app/private/pdf-diagnostic-'.bin2hex(random_bytes(6)));mkdir($dir,0700,true);file_put_contents($dir.'/check.html','<!doctype html><html><body>NUERS synthetic PDF check</body></html>');$result=[];
try{foreach(['missing_home','private_home']as$mode){$env=array_fill_keys(array_keys(array_merge(getenv(),$_ENV,$_SERVER)),false);$env['PATH']='/usr/local/bin:/usr/bin:/bin';$env['LANG']='C.UTF-8';if($mode==='private_home'){$env['HOME']=$dir;$env['TMPDIR']=$dir;$env['XDG_CONFIG_HOME']=$dir.'/config';$env['XDG_CACHE_HOME']=$dir.'/cache';}$chrome=config('document_pdf.chrome_binary');$p=new Symfony\Component\Process\Process([$chrome,'--headless=new','--no-first-run','--disable-extensions','--disable-background-networking','--disable-component-update','--disable-sync','--no-proxy-server','--host-resolver-rules=MAP * ~NOTFOUND','--user-data-dir='.$dir.'/'.$mode,'--no-pdf-header-footer','--print-to-pdf='.$dir.'/'.$mode.'.pdf','file://'.$dir.'/check.html'],$root,$env);$p->setTimeout(20);try{$p->run();$exception=null;}catch(Throwable$e){$exception=get_class($e).': '.$e->getMessage();}$result[$mode]=['pdf'=>is_file($dir.'/'.$mode.'.pdf'),'exit'=>$p->getExitCode(),'exception'=>$exception,'stderr'=>substr($p->getErrorOutput(),0,2200)];}}finally{Illuminate\Support\Facades\File::deleteDirectory($dir);}echo json_encode($result,JSON_PRETTY_PRINT).PHP_EOL;
